def _json_page(
    items: list[dict], total: int | None = None, next_cursor: str | None = None
) -> dict:
    body: dict = {"results": items}
    if total is not None:
        body["total"] = total
    if next_cursor is not None:
        body["next_cursor"] = next_cursor
    return body


